<?php
namespace CloudHost247\Ovh\Services;
use CloudHost247\Ovh\Normalization\IpNormalizer;use WHMCS\Database\Capsule;use RuntimeException;
final class ClientServiceView{public function build($serviceId,$clientId){$hosting=Capsule::table('tblhosting as h')->join('tblproducts as p','p.id','=','h.packageid')->where('h.id',(int)$serviceId)->where('h.userid',(int)$clientId)->select('h.id','h.domain','h.domainstatus','h.billingcycle','h.nextduedate','h.dedicatedip','h.packageid','p.name as product_name')->first();if(!$hosting)throw new RuntimeException('Service was not found or is not owned by this client.');$binding=Capsule::table('mod_cloudhost247_ovh_services')->where('whmcs_service_id',$hosting->id)->first();$details=$binding?json_decode($binding->details_json?:'{}',true):array();if(!is_array($details))$details=array();$meta=$this->meta($hosting->packageid);$spec=$meta['specifications'];$ips=(new IpNormalizer())->normalize(array($hosting->dedicatedip,$details['ips']??array()));return array('service'=>array('id'=>$hosting->id,'name'=>$hosting->domain?:$hosting->product_name,'product'=>$hosting->product_name,'product_kind'=>$meta['product_kind'],'status'=>$hosting->domainstatus,'billing_cycle'=>$hosting->billingcycle,'next_due_date'=>$hosting->nextduedate),'provider'=>array('service_name'=>$binding?$binding->remote_service_name:null,'provisioning'=>(new ProvisioningStatePresenter())->present($binding?$binding->status:'not_verified'),'last_sync'=>$binding?$binding->last_synced_at:null),'specifications'=>$spec,'ips'=>$ips);}
 private function meta($pid){$m=Capsule::table('mod_cloudhost247_hosting_products')->where('whmcs_product_id',$pid)->first();$v=$m?json_decode($m->specifications_json?:'{}',true):array();return array('product_kind'=>$m&&in_array($m->product_kind,array('hosting','vps','dedicated'),true)?$m->product_kind:'not_verified','specifications'=>is_array($v)?$v:array());}}
